<template>
	<div class="i360-widget i360-list">
		<div class="i360-toolbar">
			<NcActions :forceMenu="true">
				<NcActionButton @click="openSettings">
					<template #icon>
						<CogIcon :size="20" />
					</template>
					{{ t('integration_inspect360', 'Widget settings') }}
				</NcActionButton>
				<NcActionButton @click="fetch">
					<template #icon>
						<RefreshIcon :size="20" />
					</template>
					{{ t('integration_inspect360', 'Refresh now') }}
				</NcActionButton>
			</NcActions>
		</div>

		<WidgetSettingsModal
			v-if="showSettings"
			:refreshSeconds="refreshIntervalSeconds"
			:maxItems="maxItems"
			:saving="savingSettings"
			@close="showSettings = false"
			@save="onSaveSettings" />

		<div v-if="loading && !loaded" class="i360-status">
			<NcLoadingIcon :size="28" />
		</div>

		<div v-else-if="notConnected" class="i360-status">
			<LinkOffIcon :size="40" class="i360-status__icon" />
			<span>{{ t('integration_inspect360', 'Sign in to Inspect360 from Personal Settings.') }}</span>
		</div>

		<div v-else-if="hardError" class="i360-status i360-status--error">
			<AlertCircleOutlineIcon :size="40" class="i360-status__icon" />
			<span>{{ hardError }}</span>
		</div>

		<div v-else-if="!items.length" class="i360-status">
			<component :is="emptyIcon" :size="40" class="i360-status__icon" />
			<span>{{ emptyMessage }}</span>
		</div>

		<template v-else>
			<ul class="i360-rows">
				<li v-for="v in items" :key="v.id" class="i360-row">
					<a class="i360-row__link" :href="link('/vendors/' + v.id)" target="_blank" rel="noopener">
						<span class="i360-badge" :class="'i360-badge--' + badgeVariant(v.status)">
							<component :is="badgeIcon(v.status)" :size="16" />
						</span>
						<div class="i360-row__body">
							<div class="i360-row__title" :title="v.org_name">{{ v.org_name || t('integration_inspect360', '(unnamed)') }}</div>
							<div class="i360-row__meta">
								<span v-if="v.city" class="i360-row__meta-item">{{ v.city }}</span>
								<span v-if="v.country" class="i360-row__meta-item">{{ v.country }}</span>
								<span v-if="rowTime(v)" class="i360-row__meta-item i360-row__meta-item--dim">{{ rowTime(v) }}</span>
								<span v-if="v.critical_supplier_flag" class="i360-flag i360-flag--critical" :title="t('integration_inspect360', 'Critical supplier')">C</span>
								<span v-if="v.ict_provider_flag" class="i360-flag i360-flag--ict" :title="t('integration_inspect360', 'ICT provider')">ICT</span>
								<span v-if="v.data_processor_flag" class="i360-flag i360-flag--dp" :title="t('integration_inspect360', 'Data processor')">DP</span>
								<span v-if="v.aml_regulated" class="i360-flag i360-flag--aml" :title="t('integration_inspect360', 'AML regulated')">AML</span>
							</div>
						</div>
					</a>
				</li>
			</ul>

			<a
				:href="link('/vendors' + (statusFilter ? '?status=' + statusFilter : ''))"
				target="_blank"
				rel="noopener"
				class="i360-more">
				<span>{{ t('integration_inspect360', 'Show all') }}</span>
				<OpenInNewIcon :size="14" />
			</a>
		</template>
	</div>
</template>

<script>
import axios from '@nextcloud/axios'
import { generateUrl } from '@nextcloud/router'
import NcActionButton from '@nextcloud/vue/components/NcActionButton'
import NcActions from '@nextcloud/vue/components/NcActions'
import NcLoadingIcon from '@nextcloud/vue/components/NcLoadingIcon'
import AlertCircleOutlineIcon from 'vue-material-design-icons/AlertCircleOutline.vue'
import ArchiveOutlineIcon from 'vue-material-design-icons/ArchiveOutline.vue'
import CheckCircleIcon from 'vue-material-design-icons/CheckCircle.vue'
import CheckCircleOutlineIcon from 'vue-material-design-icons/CheckCircleOutline.vue'
import ClockOutlineIcon from 'vue-material-design-icons/ClockOutline.vue'
import CogIcon from 'vue-material-design-icons/Cog.vue'
import LinkOffIcon from 'vue-material-design-icons/LinkOff.vue'
import OpenInNewIcon from 'vue-material-design-icons/OpenInNew.vue'
import PencilOutlineIcon from 'vue-material-design-icons/PencilOutline.vue'
import RefreshIcon from 'vue-material-design-icons/Refresh.vue'
import WidgetSettingsModal from '../components/WidgetSettingsModal.vue'
import { useAutoRefresh } from '../composables/useAutoRefresh.js'

const STATUS_LABELS = {
	approved: 'Approved',
	draft: 'Draft',
	under_review: 'Under review',
	archived: 'Archived',
}

export default {
	name: 'VendorsListWidget',
	components: {
		NcActionButton,
		NcActions,
		NcLoadingIcon,
		WidgetSettingsModal,
		AccountPlusIcon,
		AlertCircleOutlineIcon,
		ArchiveOutlineIcon,
		CheckCircleIcon,
		CheckCircleOutlineIcon,
		ClockOutlineIcon,
		CogIcon,
		LinkOffIcon,
		OpenInNewIcon,
		PencilOutlineIcon,
		PlaylistCheckIcon,
		RefreshIcon,
	},

	props: {
		endpoint: { type: String, required: true },
		widgetKey: { type: String, required: true },
		variant: { type: String, default: 'approved' },
	},

	data() {
		return {
			loading: false,
			loaded: false,
			notConnected: false,
			hardError: null,
			items: [],
			total: 0,
			instanceUrl: '',
			refreshIntervalSeconds: 300,
			maxItems: 10,
			showSettings: false,
			savingSettings: false,
			autoRefresh: null,
		}
	},

	computed: {
		statusFilter() {
			if (this.variant === 'approved') return 'approved'
			if (this.variant === 'inprogress') return 'draft'  // ymir has no combined filter — link to drafts as a reasonable landing
			return ''
		},

		emptyMessage() {
			if (this.variant === 'added') {
				return t('integration_inspect360', 'No vendors added yet.')
			}
			if (this.variant === 'inprogress') {
				return t('integration_inspect360', 'No vendors in progress — the queue is clear.')
			}
			return t('integration_inspect360', 'No approved vendors — new approvals will appear here.')
		},

		emptyIcon() {
			if (this.variant === 'inprogress') return PlaylistCheckIcon
			if (this.variant === 'added') return AccountPlusIcon
			return CheckCircleOutlineIcon
		},
	},

	mounted() {
		this.fetch()
		this.autoRefresh = useAutoRefresh(this.fetch, this.refreshIntervalSeconds * 1000)
	},

	methods: {
		openSettings() {
			this.showSettings = true
		},

		async fetch() {
			this.loading = true
			try {
				const { data } = await axios.get(generateUrl('/apps/integration_inspect360/' + this.endpoint))
				this.items = Array.isArray(data.items) ? data.items : []
				this.total = Number(data.total) || 0
				this.instanceUrl = data.instance_url || ''
				const newInterval = Number(data.config?.refresh_interval_seconds) || 300
				if (newInterval !== this.refreshIntervalSeconds) {
					this.refreshIntervalSeconds = newInterval
					this.autoRefresh?.setIntervalMs(newInterval * 1000)
				}
				const newMax = Number(data.config?.max_items) || 10
				if (newMax !== this.maxItems) {
					this.maxItems = newMax
				}
				this.notConnected = false
				this.hardError = null
			} catch (e) {
				const status = e?.response?.status
				const err = e?.response?.data?.error
				if (status === 401 || err === 'not_connected' || err === 'no_session') {
					this.notConnected = true
				} else if (err === 'admin_not_configured') {
					this.hardError = t('integration_inspect360', 'Administrator has not configured the Inspect360 instance URL.')
				} else {
					this.hardError = t('integration_inspect360', 'Could not reach the Inspect360 API.')
				}
			} finally {
				this.loading = false
				this.loaded = true
			}
		},

		prettyStatus(s) {
			return STATUS_LABELS[s] || s || ''
		},

		badgeVariant(status) {
			if (status === 'approved') return 'approved'
			if (status === 'under_review') return 'review'
			if (status === 'draft') return 'draft'
			if (status === 'archived') return 'archived'
			return 'draft'
		},

		badgeIcon(status) {
			if (status === 'approved') return CheckCircleIcon
			if (status === 'under_review') return ClockOutlineIcon
			if (status === 'draft') return PencilOutlineIcon
			if (status === 'archived') return ArchiveOutlineIcon
			return PencilOutlineIcon
		},

		rowTime(v) {
			// Per-variant time preference:
			//   approved → approved_at (when the transition happened)
			//   inprogress → updated_at (last time the item moved)
			//   added → created_at (when the vendor was first added)
			let iso
			if (this.variant === 'approved') {
				iso = v.approved_at || v.created_at
			} else if (this.variant === 'inprogress') {
				iso = v.updated_at || v.created_at
			} else {
				iso = v.created_at
			}
			return this.relativeTime(iso)
		},

		relativeTime(iso) {
			if (!iso) return ''
			const then = new Date(iso).getTime()
			if (!then) return ''
			const diff = Math.max(0, Date.now() - then)
			const min = Math.floor(diff / 60000)
			if (min < 1) return t('integration_inspect360', 'just now')
			if (min < 60) return t('integration_inspect360', '{n} min ago', { n: min })
			const h = Math.floor(min / 60)
			if (h < 24) return t('integration_inspect360', '{n}h ago', { n: h })
			const d = Math.floor(h / 24)
			if (d < 7) return t('integration_inspect360', '{n}d ago', { n: d })
			return new Date(iso).toLocaleDateString()
		},

		link(path) {
			return (this.instanceUrl || '') + path
		},

		async onSaveSettings(payload) {
			this.savingSettings = true
			try {
				await axios.put(
					generateUrl('/apps/integration_inspect360/widget/' + this.widgetKey + '/preferences'),
					{
						refresh_seconds: payload.refreshSeconds,
						max_items: payload.maxItems,
					},
				)
				this.refreshIntervalSeconds = payload.refreshSeconds
				this.autoRefresh?.setIntervalMs(payload.refreshSeconds * 1000)
				if (payload.maxItems !== null) {
					this.maxItems = payload.maxItems
				}
				this.showSettings = false
				this.fetch()  // re-fetch to pick up the new max_items cap
			} catch { /* silent — user can retry from within the still-open modal */ }
			finally {
				this.savingSettings = false
			}
		},
	},
}
</script>

